"""SFC coverage (generated by tools/gen_lang_tests.py - do not edit by hand)."""

import unittest

from stc.compiler import compile_source


class SfcTests(unittest.TestCase):

    def test_001_sfc_minimal(self):
        source = """\
PROGRAM F01Sfc
VAR_INPUT go : BOOL; END_VAR
VAR_OUTPUT done : BOOL; END_VAR
INITIAL_STEP s0: END_STEP
TRANSITION FROM s0 TO s1 := go; END_TRANSITION
STEP s1: done(N); END_STEP
TRANSITION FROM s1 TO s0 := NOT go; END_TRANSITION
END_PROGRAM
"""
        c_result = compile_source(source, "c", standard="ed3")
        self.assertTrue(c_result.success, c_result.diagnostics or c_result.syntax_error)
        self.assertIn('__sfc_s0_active', c_result.output)
        rust_result = compile_source(source, "rust", standard="ed3")
        self.assertTrue(rust_result.success, rust_result.diagnostics or rust_result.syntax_error)
        self.assertIn('s0_active', rust_result.output)

